namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryValidateContext(principal, resource, request, out var denial))
            return denial;

        return DecideForValidContext(principal!, resource!, request!, delegations);
    }

    private static bool TryValidateContext(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision denial)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context", out denial);
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Deny("invalid-identity", out denial);
        if (principal.Suspended)
            return Deny("principal-suspended", out denial);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Deny("tenant-mismatch", out denial);
        if (resource.Locked && request.Action != "read")
            return Deny("resource-locked", out denial);
        if (request.MinuteOfDay is < 0 or > 1439)
            return Deny("invalid-time", out denial);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Deny("challenge-required", out denial);

        denial = default!;
        return false;
    }

    private static AccessDecision DecideForValidContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        if (request.BreakGlass)
            return DecideBreakGlass(administrator, request.StrongAuthentication);

        if (TryValidateAccessRequirements(resource, request, administrator, out var denial))
            return denial;

        return DecideAction(request, resource, administrator, operatorRole, auditor, owner, delegated);
    }

    private static AccessDecision DecideBreakGlass(bool administrator, bool strongAuthentication)
    {
        return administrator && strongAuthentication
            ? new AccessDecision(true, "break-glass", true)
            : new AccessDecision(false, "invalid-break-glass", true);
    }

    private static bool TryValidateAccessRequirements(
        Resource resource,
        AccessRequest request,
        bool administrator,
        out AccessDecision denial)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Deny("strong-authentication-required", out denial);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Deny("trusted-network-required", out denial);
        if (request.Action == "delete" && !administrator)
            return Deny("administrator-required", out denial);

        denial = default!;
        return false;
    }

    private static AccessDecision DecideAction(
        AccessRequest request,
        Resource resource,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        if (request.Action == "write" && !(administrator || operatorRole || owner || delegated))
            return new AccessDecision(false, "write-not-authorised", true);
        if (request.Action == "read" && !(administrator || operatorRole || auditor || owner || delegated))
            return new AccessDecision(false, "read-not-authorised", false);
        if (request.Action is not ("read" or "write" or "delete"))
            return new AccessDecision(false, "unknown-action", true);

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        var auditRequired = outsideBusinessHours || resource.Classification == "restricted";
        return new AccessDecision(true, delegated ? "delegated" : "role-or-ownership", auditRequired);
    }

    private static bool Deny(string reason, out AccessDecision denial)
    {
        denial = new AccessDecision(false, reason, true);
        return true;
    }
}
